SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0510000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 51, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "51", "printedPageNumber": 51, "pdfPageNumber": 434, "sequenceIndex": 41, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0510100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0510000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "in His word; and who realize the value of the blessings and reward in the Hereafter. It is in respect of such people that Allah says:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Men, whom neither merchandise nor sale beguileth them from remembrance of Allah and constancy in ''salaat.''\" (XXIV: 37).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said of Saalim Haddaad (Rahmatullah alaih) (a trader and a great Soofi) that on hearing Azaan he would turn pale and grow restless. He would stand up immediately, leaving his shop open and recite these couplets:-\n\n1. \"When Thy summoner stands up to summon,\nquickly I stand up.\nTo respond to (the summons of) The Mighty Lord\nWho hath no peer.\"\n\n2. \"I reply to the summons with complete submission and cheer,\n''Here am I, O Bountiful One.''\"\n\n3. \"My face grows pale with awe and fear, and occupation in Thee distracts me from all other occupations.\"\n\n4. \"I swear by Thee, naught is dear to me save Thy remembrance.\nNothing is more ravishing for me than Thy sweet name.\"\n\n5. \"O, will there be a time for us to be together?\nA lover is happy only when he is with his love.\"\n\n6. \"He whose eyes have seen the light of Thy Beauty\nCan never be solaced. He must die yearning for Thee.\"\n\nIt is said in a hadith: \"People frequenting the musjid are its pegs (dwellers). Angels are their companions and visit them when they are sick and help them when they are at their jobs.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510500-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510600-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ صلاة الرجل في جماعة تضعف على صلاته في بيته وفي سوقه خمساً وعشرين ضعفاً وذلك أنه إذا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0520000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 52, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "52", "printedPageNumber": 52, "pdfPageNumber": 435, "sequenceIndex": 42, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0520000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}, {"id": "f0520100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "توضأ فأحسن الوضوء ثم خرج إلى المسجد لا يخرجه إلا الصلاة لم يخط خطوة إلا رفعت له بها درجة وحط عنه بها خطيئة فإذا صلى لم تزل الملائكة تصلي عليه ما دام في مصلاه اللهم صل عليه اللهم ارحمه ولا يزال في صلاة ما انتظر الصلاة", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}, {"id": "f0520200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Salaat with Jamaat is twenty-five times superior to salaat which is said in a house or in a shop. It is so because when a person performs wudhu in right earnest and walks on to the musjid, with the sole intention of performing salaat, each step he takes, adds one blessing to his account and wipes out one sin therefrom. Again, if he keeps sitting in the musjid (with wudhu of course) after the salaat is over, the angels keep on seeking Allah''s blessing and forgiveness for him. And as long as he keeps sitting in the musjid waiting for salaat; he goes on earning rewards as if he is busy in salaat.\"\n\nIn Hadith No. I, the superiority of salaat with Jamaat over that offered individually is described as being twenty-seven times more, while this hadith mentions only twenty-five times. Various theologians have discussed at length this seeming inconsistency. The following are some of the explanations:\n\n1. \"This variation from twenty-five to twenty-seven is due to variation of ikhlaas (sincerity) in different individuals.\"\n\n2. \"In Sirri (quiet) salaat (i.e., Zuhr and Asr), it is twenty-five times, while in Jahri (loud) salaat (i.e., Fajr, Maghrib and Ishaa), it is twenty-seven times.\"\n\n3. \"In Fajr and Ishaa, when it is somewhat inconvenient to go out due to cold and darkness, it is twenty-seven times, but in other salaats it is twenty-five times.\"\n\n4. \"In the beginning it was twenty-five times, but subsequently Allah (by special favour on the followers of the Prophet (Sallallaho alaihe wasallam)) raised the reward to twenty-seven times.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0530000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 53, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "53", "printedPageNumber": 53, "pdfPageNumber": 436, "sequenceIndex": 43, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0530000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 53"}, {"id": "f0530100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Some others have brought forward a still finer explanation. They say that the reward for salaat with Jamaat mentioned in this Hadith is not merely 25 times but a doubling (2 raised to the power) twenty-five times, which comes to 33,554,432 times. This is something not beyond the bountiful Mercy of Allah. When neglect of one salaat can cause punishment in Hell for one Huqb (as we have seen in the last chapter), so much reward for one salaat with Jamaat is quite conceivable.\n\nThe Prophet (Sallallaho alaihe wasallam) has also explained to us how the reward goes on increasing in the case of a person who, after performing wudhu, leaves his house with the sole intention of joining Jamaat for salaat in the musjid. Each step he takes, brings one reward as well as washes away one sin. Banu Salama, a clan in Madina, had their houses at some distance. They intended to shift close to the musjid. The Prophet (Sallallaho alaihe wasallam) however, advised them saying: \"Stay where you are. Every step you take when coming to musjid is written in your account.\" It is said in a hadith: \"The likeness of a person performing wudhu at home and then leaving for musjid is as the likeness of a person who, after dressing in the ihraam (Hajj apparel) at his house, leaves for Hajj.\"\n\nFurther, in the same hadith, the Prophet (Sallallaho alaihe wasallam) points to another act of great value; i.e., as long as one remains sitting in musjid after the salaat is over, the angels pray for him asking for forgiveness and mercy. The angels are the innocent and holy creation of Allah. So, the effectiveness of their prayers is self-evident.\n\nMuhammad bin Samaak (Rahmatullah alaih) is a famous theologian and Sheikh. He died at the age of one hundred and three. He used to perform two hundred rakaats of nafl salaat daily. He writes: \"For forty years, I never missed the first takbeer of salaat with Jamaat, except once when my mother had died.\" The same Shaikh writes: \"Once I missed the Jamaat. As I knew that salaat with Jamaat was twenty-five times superior, I repeated this salaat (individually) twenty-five times to make up the loss. I heard in my dream some one saying to me, ''Muhammad! You have repeated your salaat 25 times (in the hope of making good the loss), but what about the ''Aameen'' by the Angels?\" It is reported in many ahaadith that when the Imaam says ''Aameen'' after Fatihah, the Angels also say Aameen and all the past sins of a person whose Aameen coincides with that of the Angels are forgiven. This is", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 53"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0540000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 54, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "54", "printedPageNumber": 54, "pdfPageNumber": 437, "sequenceIndex": 44, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0540100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0540000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "possible only in a salaat with jamaat, hence Maulana Abdul Hayy quoting this story about the Shaikh writes: \"Even if a person goes on repeating his salaat (individually) a thousand times, he cannot get the collective blessing of a salaat with Jamaat.\" This is obvious. He not only loses ''Aameen'' with the Angels, but also the blessings of the congregation and the prayers of the Angels after salaat, with many other spiritual benefits. This should also be borne in mind that the prayers of Angels can be deserved only when the salaat is a proper one. If the salaat of a person is not as it should be (according to hadith) it is flung back like a dirty rag at his face, then how can the Angels pray for him?", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540200-0000-4000-8000-000000000001", "structuralNodeId": "b0540100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540300-0000-4000-8000-000000000001", "structuralNodeId": "b0540100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن مسعود رضي الله عنه قال من سره أن يلقى الله غداً مسلماً فليحافظ على هؤلاء الصلوات حيث ينادى بهن فإن الله تعالى شرع لنبيكم ﷺ سنن الهدى وإنهن من سنن الهدى ولو أنكم صليتم في بيوتكم كما يصلي هذا المتخلف في بيته لتركتم سنة نبيكم ولو تركتم سنة نبيكم لضللتم وما من رجل يتطهر فيحسن الطهور ثم يعمد إلى مسجد من هذه المساجد إلا كتب الله له بكل خطوة يخطوها حسنة ويرفعه بها درجة ويحط عنه بها سيئة ولقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق ولقد كان الرجل يؤتى به يهادى بين الرجلين حتى يقام في الصف وفي رواية ولقد رأيتنا وما يتخلف عن الصلاة إلا منافق قد علم نفاقه أو مريض إن كان الرجل ليمشي بين الرجلين حتى يأتي الصلاة وقال إن رسول الله ﷺ علمنا سنن الهدى وإن من سنن الهدى الصلاة في المسجد الذي يؤذن فيه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540400-0000-4000-8000-000000000001", "structuralNodeId": "b0540100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Masood (Radhiyallaho anho) says: \"If one wishes to meet Allah on the Day of Judgement as a Muslim, he must say his salaat at a place where Azaan is called out, viz., a musjid, as Allah has prescribed through His Prophet (Sallallaho alaihe wasallam) such practices which are nothing but guidance through and through; and salaat (with Jamaat) is one of them. If you start saying your salaat at your houses (as so and so is doing), then you will be dis-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0550000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 55, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "55", "printedPageNumber": 55, "pdfPageNumber": 438, "sequenceIndex": 45, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0550100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith IV", "sourceIdentifier": "IV", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0550000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "carding the Sunnah of the Prophet (Sallallaho alaihe wasallam) and no sooner you desert his Sunnah than you go astray. When a person performs wudhu correctly and then leaves for the musjid, at each step that he takes, he gets one blessing and has one sin wiped out. During the lifetime of the Prophet (Sallallaho alaihe wasallam) no one would miss Jamaat except an open munaafiq or a real invalid. Even the munaafiq dared not miss the Jamaat and a sick person who could be taken to the musjid with the help of two men would be helped to join Jamaat.\"\n\nThis shows the extreme vigilance of the Sahabah over their salaat with Jamaat. Even a sick person was brought to the musjid somehow or other, even though it needed two men to help him. This concern was quite natural when they found the Prophet (Sallallaho alaihe wasallam) himself so very particular about it. It is said that when the Prophet (Sallallaho alaihe wasallam) was on his deathbed, and he would frequently faint; he succeeded in making wudhu after several attempts and, though he could hardly stand, went to the musjid with the help of Hadhrat Abbas (Radhiyallaho anho) and another companion. Hadhrat Abu Bakr (Radhiyallaho anho) led the salaat at his instance, and he himself joined the Jamaat.\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates that the Prophet (Sallallaho alaihe wasallam) once said to him, \"Worship your Lord as if you see Him before you, count yourself among the dead, beware of the curse of the wronged ones and, even if you could crawl to the musjid, do not miss Ishaa and Fajr with Jamaat.\"\n\nIt is said in another hadith, \"Ishaa and Fajr are very heavy on those who are munaafiq. If they knew the reward of the Jamaat, they would go to the musjid and join the Jamaat even if they had to crawl.\"\n\n", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas bin Maalik (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550300-0000-4000-8000-000000000001", "structuralNodeId": "b0550100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550400-0000-4000-8000-000000000001", "structuralNodeId": "b0550100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أنس بن مالك رضي الله عنه قال قال رسول الله ﷺ من صلى لله أربعين يوماً في جماعة يدرك التكبيرة الأولى كتب له براءتان براءة من النار وبراءة من النفاق رواه الترمذي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}]}'::jsonb);